+            unique_lock<mutex> locker(globalLock);
+            didGetToHook = true;
+            globalCond.notify_all();
+            while (!hookShouldStop && !isHoldingContendedLocks())
+                globalCond.wait(locker);
+            hookDidStop = true;
+        };
